module tb;
    // Declare inputs as regs, outputs as wires
    reg [7:0] a;
    reg [7:0] b;
    wire [7:0] s;
    wire overflow;

    // Instantiate TopModule dut
    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    integer errors = 0;

    // Task to check results against expected values
    task check_result;
        input [7:0] exp_s;
        input exp_ovf;
        begin
            #1; // Allow propagation delay
            if (s !== exp_s || overflow !== exp_ovf) begin
                $display("ERROR: a=%d, b=%d | Got s=%d (exp %d), overflow=%b (exp %b)", 
                         $signed(a), $signed(b), $signed(s), $signed(exp_s), overflow, exp_ovf);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Test Case 1: Positive + Positive, no overflow
        a = 8'd10; b = 8'd20;
        check_result(8'd30, 1'b0);

        // Test Case 2: Positive + Positive, overflow (e.g., 100 + 50 = 150 -> -106)
        a = 8'd100; b = 8'd50;
        check_result(8'd150, 1'b1);

        // Test Case 3: Negative + Negative, no overflow
        a = -8'd10; b = -8'd20;
        check_result(-8'd30, 1'b0);

        // Test Case 4: Negative + Negative, overflow (e.g., -100 + -50 = -150 -> 106)
        a = -8'd100; b = -8'd50;
        check_result(-8'd150, 1'b1);

        // Test Case 5: Positive + Negative, never overflows signed addition
        a = 8'd50; b = -8'd20;
        check_result(8'd30, 1'b0);

        // Test Case 6: Negative + Positive, never overflows signed addition
        a = -8'd50; b = 8'd20;
        check_result(-8'd30, 1'b0);

        // Test Case 7: Zero + Zero
        a = 8'd0; b = 8'd0;
        check_result(8'd0, 1'b0);

        // Test Case 8: Max positive + (-1)
        a = 8'sd127; b = -8'sd1;
        check_result(8'sd126, 1'b0);

        // Test Case 9: Max positive + positive 1 (Overflow to Min negative)
        a = 8'sd127; b = 8'sd1;
        check_result(-8'sd128, 1'b1);

        // Test Case 10: Min negative + (-1) (Overflow to Max positive)
        a = -8'sd128; b = -8'sd1;
        check_result(8'sd127, 1'b1);

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
